 "spec": {
  "metric": "connected_retention",
  "title": "Weekly retention by first-week connection",
  "question": "Do members who connect with others in their first 7 days stay longer than those who do not?",
  "sql": "WITH periods(period) AS (VALUES (1), (2), (3), (4), (5), (6), (7), (8)),\nbase AS (\n  SELECT member_id, signup_week AS cohort, signup_at,\n         CASE connected_state WHEN 'reached' THEN 'connected' ELSE 'unconnected' END AS series\n  FROM d_member_first_week\n  WHERE board_state = 'reached'\n)\nSELECT b.cohort, b.series, p.period,\n       sum(w.member_id IS NOT NULL) AS numerator,\n       count(*) AS denominator\nFROM base b\nJOIN periods p\n  ON strftime('%Y-%m-%d %H:%M:%S', b.signup_at, '+' || (7 * (p.period + 1)) || ' days') || substr(b.signup_at, 20) <= :as_of\nLEFT JOIN d_member_activity_week w\n  ON w.member_id = b.member_id AND w.life_week = p.period AND w.any_cnt > 0\nGROUP BY b.cohort, b.series, p.period\nORDER BY b.cohort, b.series, p.period",
  "display": {
   "type": "cohort",
   "cohort": "cohort",
   "period": "period",
   "numerator": "numerator",
   "denominator": "denominator",
   "series": "series"
  },
  "definition": [
   [
    "Population",
    "Members who joined a board within 7 days of signup"
   ],
   [
    "Groups",
    "connected: shared a board with another member within 7 days / unconnected: did not"
   ],
   [
    "Retention",
    "Wn = at least one post, comment or like in days [7n, 7n+7) after signup"
   ],
   [
    "Denominator",
    "Only members whose window has fully passed by the cutoff (observable)"
   ]
  ],
  "caveats": [
   "Selection bias: members who are more active in their first week also connect more easily",
   "Members who left are kept in the denominator and counted as inactive"
  ],
